"lean_claims": [
{"theorem": "strongThinTree", "line": 38, "plain": "There exists real C > 0 such that for all k ≥ 1, all n ≥ 2, all m, and every loopless multigraph G on n vertices with m edges that is k-edge-connected, there exists a spanning tree T ⊆ E(G) with |δ_T(S)| ≤ (C/k)·|δ_G(S)| for all ∅ ≠ S ⊊ V."}
],
"paper_claims": [
{"ref": "Theorem 1.1", "plain": "There is an absolute constant C such that, given a finite k-edge-connected multigraph G on at least one vertex and k ≥ 1, a deterministic algorithm returns, in time polynomial in the binary input length (explicit edges or binary multiplicities), a spanning tree T with |δ_T(S)| ≤ (C/k)|δ_G(S)| for all ∅ ≠ S ⊊ V(G). For one vertex the answer is the empty tree."}
